"""Illustrative energy and spend data for the Waffle view (invented). energy_mix.csv: electricity generated by
source and nation for 2025 (GWh). spend.csv: an organisation's annual spend by category and region."""
import csv, random
random.seed(33)
mix = {"Wind": 30, "Gas": 32, "Nuclear": 14, "Solar": 5, "Biomass": 6, "Hydro": 2, "Imports": 9, "Other": 2}
adj = {"England": {}, "Scotland": {"Wind": 2.1, "Gas": .3, "Hydro": 4}, "Wales": {"Gas": 1.4, "Wind": .9, "Nuclear": 0.01}, "Northern Ireland": {"Wind": 1.4, "Gas": 1.3, "Nuclear": 0.01, "Imports": .5}}
size = {"England": 220000, "Scotland": 30000, "Wales": 22000, "Northern Ireland": 8000}
rows = []
for n, tot in size.items():
    w = {s: v * adj[n].get(s, 1) * random.uniform(.9, 1.1) for s, v in mix.items()}; t = sum(w.values())
    for s, v in w.items(): rows.append([n, s, round(tot * v / t)])
with open("energy_mix.csv", "w", newline="") as f:
    wr = csv.writer(f); wr.writerow(["Nation", "Source", "Generation (GWh)"]); wr.writerows(rows)
print(len(rows))
